        """Read all files from a GitHub repository."""
        try:
            files = self.github_utils.get_all_files_content(repository, branch)
            return str(files)
        except Exception as e:
            return f"Error: {str(e)}"

    def _get_file(self, repository: str, file_path: str, branch: str = "main") -> str:
        """Get content of a specific file."""
        try:
            file_data = self.github_utils.get_file_content(repository, file_path, branch)
            return file_data['content']
        except Exception as e:
            return f"Error: {str(e)}"

    def _list_files(self, repository: str, branch: str = "main") -> str:
        """List all files in repository."""
        try:
            files = self.github_utils.get_repository_tree(repository, branch)
            return "\n".join([f['path'] for f in files])
        except Exception as e:
            return f"Error: {str(e)}"

    def get_tools(self):
        """Return all tools as StructuredTool objects"""
        return [
            StructuredTool.from_function(
                func=self._read_repository,
                name="read_repository",
                description="Read all files from a GitHub repository. Use this when you need to access the entire codebase."
            ),
            StructuredTool.from_function(
                func=self._get_file,
                name="get_file",
                description="Get content of a specific file from repository. Use this when you need a specific file's content."
            ),
            StructuredTool.from_function(
                func=self._list_files,
                name="list_files",
                description="List all files in a repository. Use this to see the repository structure."
            )
        ]
